import { query, mutation } from "./_generated/server";
import { internal } from "./_generated/api";
import { Doc } from "./_generated/dataModel";
import { v } from "convex/values";
import { Id } from "./_generated/dataModel";

/**
 * Fetches the daily quests for the user.
 * These are micro-goals created during onboarding, generated by the system, or added manually.
 */
export const getDailyQuests = query({
  args: {},
  handler: async (ctx): Promise<Doc<"userPresets">[]> => {
    const user: Doc<"users"> | null = await ctx.runQuery(internal.users.getCurrentUser);
    if (!user) {
      return [];
    }

    // Fetch all presets for the user
    const allUserPresets = await ctx.db
      .query("userPresets")
      .withIndex("by_user", (q) => q.eq("userId", user._id))
      .collect();

    // Filter for the sources that count as daily quests.
    // This includes goals from onboarding, custom goals, and AI-generated system goals.
    const dailyQuests = allUserPresets.filter(p => 
      p.source === "onboarding" || p.source === "custom" || p.source === "system"
    );

    return dailyQuests;
  },
});

/**
 * Completes a daily quest, creating an achievement and awarding points.
 */
export const completeDailyQuest = mutation({
  args: {
    presetId: v.id("userPresets"),
  },
  handler: async (ctx, { presetId }) => {
    const user = await ctx.runQuery(internal.users.getCurrentUser);
    if (!user) {
      throw new Error("Not authenticated");
    }

    const preset = await ctx.db.get(presetId);
    if (!preset || preset.userId !== user._id) {
      throw new Error("Quest not found or not owned by user");
    }

    // This will create an achievement, award points, and update streaks
    await ctx.runMutation(internal.achievements.createAchievement, {
      userId: user._id,
      clientId: `quest-${presetId}-${Date.now()}`,
      title: preset.title,
      description: "Completed a daily quest.",
      categorySlug: preset.categorySlug,
      source: "quick",
      isPublic: !preset.defaultPrivate,
    });

    return { title: preset.title };
  },
});

export const debugUserPresets = query({
  args: {},
  handler: async (ctx): Promise<Array<{ title: string; source: string; categorySlug: string }>> => {
    const user = await ctx.runQuery(internal.users.getCurrentUser);
    if (!user) return [];
    
    const presets = await ctx.db
      .query("userPresets")
      .withIndex("by_user", (q) => q.eq("userId", user._id))
      .collect();
    
    return presets.map(p => ({ title: p.title, source: p.source, categorySlug: p.categorySlug }));
  },
});

export const deleteAllMyPresets = mutation({
  args: {},
  handler: async (ctx): Promise<{ deletedCount: number }> => {
    const user = await ctx.runQuery(internal.users.getCurrentUser);
    if (!user) {
      throw new Error("Not authenticated");
    }

    const presets = await ctx.db
      .query("userPresets")
      .withIndex("by_user", (q) => q.eq("userId", user._id))
      .collect();

    for (const preset of presets) {
      await ctx.db.delete(preset._id);
    }

    return { deletedCount: presets.length };
  },
});